class Solution {
public:
    std::vector<std::string> removeSubfolders(std::vector<std::string>& folder) {
        std::sort(folder.begin(), folder.end());
        std::vector<std::string> res;
        for (const auto& f : folder) {
            if (res.empty()) {
                res.push_back(f);
            } else {
                std::string parent = res.back() + '/';
                if (f.rfind(parent, 0) != 0) {
                    res.push_back(f);
                }
            }
        }
        return res;
    }
};

class Solution {
    public java.util.List<String> removeSubfolders(String[] folder) {
        java.util.Arrays.sort(folder);
        java.util.List<String> res = new java.util.ArrayList<>();
        for (String f : folder) {
            if (res.isEmpty() || !f.startsWith(res.get(res.size() - 1) + "/")) {
                res.add(f);
            }
        }
        return res;
    }
}

var removeSubfolders = function(folder) {
    folder.sort();
    const res = [];
    for (const f of folder) {
        if (res.length === 0 || !f.startsWith(res[res.length - 1] + '/')) {
            res.push(f);
        }
    }
    return res;
};
